bool StructTraits<::ash::cloud_upload::mojom::DialogTask::DataView, ::ash::cloud_upload::mojom::DialogTaskPtr>::Read(
    ::ash::cloud_upload::mojom::DialogTask::DataView input,
    ::ash::cloud_upload::mojom::DialogTaskPtr* output) {
  bool success = true;
  ::ash::cloud_upload::mojom::DialogTaskPtr result(::ash::cloud_upload::mojom::DialogTask::New());
  
      if (success)
        result->position = input.position();
      if (success && !input.ReadTitle(&result->title))
        success = false;
      if (success && !input.ReadAppId(&result->app_id))
        success = false;
      if (success && !input.ReadIconUrl(&result->icon_url))
        success = false;
  *output = std::move(result);
  return success;
}


